export function refInfo(topic, rel) {
  const v = REF_INFO[`${topic}|${rel}`];
  if (!v) return null;
  const map = !v[0] ? '' : v[0].startsWith('http') ? v[0] : `https://goo.gl/maps/${v[0]}`;
  return { map, desc: v[1], lat: v[2] ?? null, lng: v[3] ?? null };
}
